import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './fichiersCSS/StudentNotes.css';

function StudentNotes() {
  const navigate = useNavigate();
  const [notes, setNotes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      navigate('/login');
      return;
    }
    fetchNotes();
  }, [navigate]);

  const fetchNotes = async () => {
    try {
      setLoading(true);
      setError('');
      
      const token = localStorage.getItem('token');
      const user = JSON.parse(localStorage.getItem('user'));
      
      console.log('🔍 Utilisateur:', user);
      console.log('🔍 Token présent:', !!token);
      
      if (!user || !user.id) {
        setError('Utilisateur non connecté');
        setLoading(false);
        return;
      }

      // Essayer plusieurs endpoints possibles avec plus de détails
      const endpoints = [
        `/api/students/${user.id}/grades`,
        `/api/etudiants/${user.id}/notes`,
        '/api/notes/etudiant',
        '/api/grades/student',
        '/api/student/grades',
        '/api/mes-notes',
        '/api/notes',
        `/api/users/${user.id}/grades`
      ];

      let notesData = [];
      let successfulEndpoint = '';
      
      for (const endpoint of endpoints) {
        try {
          console.log(`🔄 Essai endpoint: http://localhost:5000${endpoint}`);
          const fullUrl = `http://localhost:5000${endpoint}`;
          
          const response = await fetch(fullUrl, {
            method: 'GET',
            headers: { 
              'Authorization': `Bearer ${token}`,
              'Content-Type': 'application/json'
            }
          });

          console.log(`📡 Statut pour ${endpoint}:`, response.status);
          
          if (response.ok) {
            const data = await response.json();
            console.log(`✅ Réponse de ${endpoint}:`, data);
            
            // Analyser la structure des données
            if (Array.isArray(data)) {
              notesData = data;
              successfulEndpoint = endpoint;
            } else if (data.grades && Array.isArray(data.grades)) {
              notesData = data.grades;
              successfulEndpoint = endpoint;
            } else if (data.notes && Array.isArray(data.notes)) {
              notesData = data.notes;
              successfulEndpoint = endpoint;
            } else if (data.data && Array.isArray(data.data)) {
              notesData = data.data;
              successfulEndpoint = endpoint;
            } else if (typeof data === 'object') {
              // Essayer de trouver un tableau dans l'objet
              const arrayKeys = Object.keys(data).filter(key => Array.isArray(data[key]));
              if (arrayKeys.length > 0) {
                notesData = data[arrayKeys[0]];
                successfulEndpoint = endpoint;
                console.log(`📊 Tableau trouvé dans la clé: ${arrayKeys[0]}`);
              }
            }
            
            if (notesData.length > 0) {
              console.log(`🎉 SUCCÈS avec ${endpoint}: ${notesData.length} notes chargées`);
              break;
            } else {
              console.log(`ℹ️ Endpoint ${endpoint} réussi mais données vides`);
            }
          } else {
            console.log(`❌ Endpoint ${endpoint} échoué:`, response.status);
            // Essayer de lire le message d'erreur
            try {
              const errorText = await response.text();
              console.log(`📝 Message d'erreur:`, errorText);
            } catch (e) {
              console.log('Impossible de lire le message d\'erreur');
            }
          }
        } catch (error) {
          console.log(`💥 Erreur réseau pour ${endpoint}:`, error.message);
        }
      }

      if (notesData.length > 0) {
        setNotes(notesData);
        console.log(`📊 ${notesData.length} notes chargées depuis ${successfulEndpoint}`);
        console.log('Exemple de note:', notesData[0]);
      } else {
        setNotes([]);
        console.log('❌ Aucune donnée reçue de tous les endpoints');
        setError('Aucune note trouvée. Vérifiez que des notes vous ont été attribuées.');
      }

    } catch (error) {
      console.error('💥 Erreur générale:', error);
      setError('Erreur de connexion au serveur. Vérifiez que le serveur est démarré.');
    } finally {
      setLoading(false);
    }
  };

  const handleBack = () => {
    navigate('/dashboard-student');
  };

  const getNoteColor = (note) => {
    const numericNote = parseFloat(note);
    if (isNaN(numericNote)) return '#6b7280';
    if (numericNote >= 16) return '#48bb78';
    if (numericNote >= 12) return '#4299e1';
    if (numericNote >= 10) return '#ed8936';
    return '#e53e3e';
  };

  const getNoteStatus = (note) => {
    const numericNote = parseFloat(note);
    if (isNaN(numericNote)) return 'Non noté';
    if (numericNote >= 10) return 'Admis';
    return 'Non admis';
  };

  const calculateStats = () => {
    if (notes.length === 0) return null;
    
    const validNotes = notes.filter(note => note.note != null && !isNaN(parseFloat(note.note)));
    if (validNotes.length === 0) return null;
    
    const total = validNotes.reduce((sum, noteItem) => {
      return sum + parseFloat(noteItem.note);
    }, 0);
    
    const moyenne = total / validNotes.length;
    const admis = validNotes.filter(noteItem => parseFloat(noteItem.note) >= 10).length;
    const nonAdmis = validNotes.filter(noteItem => parseFloat(noteItem.note) < 10).length;
    
    return {
      moyenne: moyenne.toFixed(2),
      admis,
      nonAdmis,
      total: validNotes.length
    };
  };

  const stats = calculateStats();

  if (loading) {
    return (
      <div className="loading-container">
        <div className="spinner"></div>
        <p>Chargement de vos notes...</p>
      </div>
    );
  }

  return (
    <div className="student-notes-container">
      <header className="student-notes-header">
        <button onClick={handleBack} className="back-button">
          ← Retour au Dashboard
        </button>
        <h1 className="title">Mes Notes</h1>
        <div className="header-actions">
          <span className="counter">
            {notes.length} note{notes.length > 1 ? 's' : ''}
          </span>
          <button onClick={fetchNotes} className="refresh-button">
            🔄 Actualiser
          </button>
        </div>
      </header>

      <main className="student-notes-main">
        {error && (
          <div className="error-alert">
            <div className="error-content">
              <strong>Erreur:</strong> {error}
            </div>
            <button onClick={fetchNotes} className="retry-button">
              🔄 Réessayer
            </button>
          </div>
        )}

        {/* Section de debug - à retirer en production */}
        <div className="debug-info" style={{ 
          background: '#f3f4f6', 
          padding: '10px', 
          borderRadius: '8px', 
          marginBottom: '20px',
          fontSize: '12px',
          color: '#6b7280'
        }}>
          <strong>Info debug:</strong> Ouvrez la console (F12) pour voir les détails des requêtes API
        </div>

        {stats && (
          <div className="stats-grid">
            <div className="stat-card">
              <div className="stat-number">{stats.moyenne}</div>
              <div className="stat-label">Moyenne Générale</div>
            </div>
            <div className="stat-card">
              <div className="stat-number" style={{color: '#48bb78'}}>{stats.admis}</div>
              <div className="stat-label">Notes ≥ 10</div>
            </div>
            <div className="stat-card">
              <div className="stat-number" style={{color: '#e53e3e'}}>{stats.nonAdmis}</div>
              <div className="stat-label">Notes &lt; 10</div>
            </div>
            <div className="stat-card">
              <div className="stat-number">{stats.total}</div>
              <div className="stat-label">Notes valides</div>
            </div>
          </div>
        )}

        {notes.length === 0 && !loading ? (
          <div className="empty-state">
            <div className="empty-icon">📊</div>
            <h3>Aucune note disponible</h3>
            <p>Vos notes apparaîtront ici une fois publiées par vos professeurs.</p>
            <div className="empty-actions">
              <button onClick={fetchNotes} className="retry-button">
                🔄 Vérifier à nouveau
              </button>
              <button onClick={handleBack} className="back-button">
                ← Retour au dashboard
              </button>
            </div>
          </div>
        ) : (
          <div className="notes-table">
            <div className="table-header">
              <h3>Détail des notes</h3>
              <span className="table-info">
                {notes.length} note{notes.length > 1 ? 's' : ''} au total
              </span>
            </div>
            <table className="table">
              <thead>
                <tr>
                  <th className="th">Cours</th>
                  <th className="th">Niveau</th>
                  <th className="th">Note</th>
                  <th className="th">Statut</th>
                  <th className="th">Professeur</th>
                  <th className="th">Date</th>
                </tr>
              </thead>
              <tbody>
                {notes.map((note, index) => (
                  <tr key={note.id || index} className="tr">
                    <td className="td">
                      <strong>{note.course_title || note.cours_nom || note.matiere || 'Non spécifié'}</strong>
                    </td>
                    <td className="td">
                      <span className="level-badge">
                        {note.course_level || note.niveau || note.level || 'N/A'}
                      </span>
                    </td>
                    <td className="td">
                      <span 
                        className="note-badge"
                        style={{ background: getNoteColor(note.note) }}
                      >
                        {note.note}/20
                      </span>
                    </td>
                    <td className="td">
                      <span 
                        className="status-badge"
                        style={{
                          background: parseFloat(note.note) >= 10 ? '#c6f6d5' : '#fed7d7',
                          color: parseFloat(note.note) >= 10 ? '#22543d' : '#742a2a'
                        }}
                      >
                        {getNoteStatus(note.note)}
                      </span>
                    </td>
                    <td className="td">
                      {note.professeur_nom || note.teacher_name || note.professor || 'Non spécifié'}
                    </td>
                    <td className="td">
                      {note.date_evaluation || note.evaluation_date || note.date ? 
                        new Date(note.date_evaluation || note.evaluation_date || note.date).toLocaleDateString('fr-FR') : 
                        'Non spécifiée'
                      }
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>
    </div>
  );
}

export default StudentNotes;
